#!/usr/bin/env bash
# Creates a local .env with random secrets for `make up`. Never overwrites an existing file, so
# running it again (or from CI) is safe. Optional variables are documented in .env.example.
set -euo pipefail

target="${1:-.env}"

if [[ -e "$target" ]]; then
  echo "$target already exists: left untouched"
  exit 0
fi

# Hex only: the database password is embedded in a postgresql:// URL.
random_hex() {
  od -An -N"$1" -tx1 /dev/urandom | tr -d ' \n'
}

umask 077
cat > "$target" <<ENV
# Generated by scripts/gen-env.sh for local development. Never commit this file.
# Every variable is documented in .env.example.
IBERGRID_S3_ACCESS_KEY=ibergrid-$(random_hex 8)
IBERGRID_S3_SECRET_KEY=$(random_hex 24)
LAKEKEEPER_DB_PASSWORD=$(random_hex 24)
LAKEKEEPER_ENCRYPTION_KEY=$(random_hex 32)
DAGSTER_DB_PASSWORD=$(random_hex 24)
REDPANDA_ADMIN_PASSWORD=$(random_hex 24)
REDPANDA_PRODUCER_PASSWORD=$(random_hex 24)
REDPANDA_CONSUMER_PASSWORD=$(random_hex 24)
ENV

echo "created $target with random local secrets"
